package store

import "os"

func save(path string, data []byte) error {
	tmp, err := os.CreateTemp("", "x-*")
	if err != nil {
		return err
	}
	tmp.Write(data)
	tmp.Close()
	return os.Rename(tmp.Name(), path)
}

